/** Options that influence how a post-processed glTF is turned into a luma.gl scenegraph. */
export type ParseGLTFOptions = {
  /** Resolved host properties for animation pointers, such as physics motion and drives. */
  properties?: import('@luma.gl/engine').InteractivityPropertyAdapter | null;
  /** Borrowed rigid GPU matrices. The renderer selects a body and local transform per draw. */
  publishedTransforms?: Buffer | null;
  /** Additional model props applied to each generated primitive model. */
  modelOptions?: Partial<ModelProps>;
  /** Enables shader-level PBR debug output. */
  pbrDebug?: boolean;
  /**
   * Optional image-based lighting environment: a loaded `PBREnvironment`, or a
   * `PBRLightingEnvironment` such as the textures of `createPrefilteredEnvironment`.
   */
  imageBasedLightingEnvironment?: PBREnvironment | PBRLightingEnvironment;
  /** Enables punctual light extraction. */
  lights?: boolean;
  /** Enables tangent usage when available. */
  useTangents?: boolean;
  /** When true, parsed semantic light colors are converted into luma.gl's legacy byte-style range. */
  useByteColors?: boolean;
  /** Leave Gaussian primitives for a caller-managed splat renderer instead of creating mesh models. */
  excludeGaussianSplatPrimitives?: boolean;
  /** Resolve supported billboard attachments into an engine controller during scene creation. */
  billboards?: {allowLegacyYAxis?: boolean} | null;
  /** Reject documents whose required extensions have no complete runtime implementation. */
  strictExtensions?: boolean;
};

type ParseGLTFInternalOptions = Required<ParseGLTFOptions> & {
  generatedTextures: Set<Texture>;
  materialInstances: Map<number, Material[]>;
  validateAttributes?: boolean;
  materialResourcesOnly?: boolean;
  validateLightmapAttributes?: boolean;
};

const defaultOptions: Required<ParseGLTFOptions> = {
  properties: null,
  billboards: null,
  publishedTransforms: null,
  modelOptions: {},
  pbrDebug: false,
  imageBasedLightingEnvironment: undefined!,
  lights: true,
  useTangents: false,
  useByteColors: true,
  strictExtensions: false,
  excludeGaussianSplatPrimitives: false
};

/**
 * GLTF instantiator for luma.gl
 * Walks the parsed and resolved glTF structure and builds a luma.gl scenegraph
 */
export function parseGLTF(
  device: Device,
  gltf: GLTFPostprocessed,
  options: ParseGLTFOptions = {}
): {
  /** Scene roots generated from `gltf.scenes`. */
  scenes: GroupNode[];
  /** Materials aligned with the source `gltf.materials` array. */
  materials: Material[];
  /** Map from glTF mesh ids to generated mesh group nodes. */
  gltfMeshIdToNodeMap: Map<string, GroupNode>;
  /** Map from glTF node indices to generated scenegraph nodes. */
  gltfNodeIndexToNodeMap: Map<number, GroupNode>;
  /** Map from glTF node ids to generated scenegraph nodes. */
  gltfNodeIdToNodeMap: Map<string, GroupNode>;
  /** Textures generated while parsing source materials, primitives, and variants. */
  generatedTextures: Set<Texture>;
  materialInstances: Map<number, Material[]>;
} {
  const generatedTextures = new Set<Texture>();
  const materialInstances = new Map<number, Material[]>();
  const combinedOptions: ParseGLTFInternalOptions = {
    ...defaultOptions,
    ...options,
    generatedTextures,
    materialInstances
  };
  const materialFactory = new MaterialFactory(device, {modules: [pbrMaterial]});
  const materials = (gltf.materials || []).map((gltfMaterial, materialIndex) =>
    createGLTFMaterial(device, {
      id: getGLTFMaterialId(gltfMaterial, materialIndex),
      parsedPPBRMaterial: parseOwnedPBRMaterial(
        device,
        gltfMaterial as any,
        // Shared material resources must include secondary-UV textures before any primitive is visited.
        // The primitive pass below validates its actual texture-coordinate attributes.
        {TEXCOORD_1: true},
        {
          ...combinedOptions,
          gltf,
          validateAttributes: false,
          materialResourcesOnly: true
        }
      ),
      materialFactory
    })
  );
  const gltfMaterialIdToMaterialMap = new Map<string, Material>();
  (gltf.materials || []).forEach((gltfMaterial, materialIndex) => {
    gltfMaterialIdToMaterialMap.set(gltfMaterial.id, materials[materialIndex]);
  });

  const gltfMeshIdToNodeMap = new Map<string, GroupNode>();
  gltf.meshes.forEach((gltfMesh, idx) => {
    const newMesh = createNodeForGLTFMesh(device, gltfMesh, gltf, gltfMaterialIdToMaterialMap, {
      ...combinedOptions,
      validateLightmapAttributes: false
    });
    gltfMeshIdToNodeMap.set(gltfMesh.id, newMesh);
  });

  const gltfNodeIndexToNodeMap = new Map<number, GroupNode>();
  const gltfNodeIdToNodeMap = new Map<string, GroupNode>();
  // Step 1/2: Generate a GroupNode for each gltf node. (1:1 mapping).
  const assignedMorphMeshes = new Set<string>();
  const assignedMeshes = new Set<string>();
  const independentlySkinnedMeshes = new Set<string>();
  gltf.nodes.forEach((gltfNode, idx) => {
    const newNode = createNodeForGLTFNode(device, gltfNode, combinedOptions);
    gltfNodeIndexToNodeMap.set(idx, newNode);
    gltfNodeIdToNodeMap.set(gltfNode.id, newNode);
  });

  // Step 2/2: Go though each gltf node and attach the children.
  // This guarantees that each gltf node will have exactly one luma GroupNode.
  gltf.nodes.forEach((gltfNode, idx) => {
    gltfNodeIndexToNodeMap.get(idx)!.add(
      (gltfNode.children ?? []).map(({id}) => {
        const child = gltfNodeIdToNodeMap.get(id);
        if (!child) throw new Error(`Cannot find child ${id} of node ${idx}`);
        return child;
      })
    );

    // Nodes can have children nodes and one optional child mesh at the same time.
    if (gltfNode.mesh) {
      const sourceMesh = gltfNode.mesh;
      const instancing = getGLTFNodeInstancing(gltf, gltfNode);
      const nodeLightmap = gltfNode.extensions?.['KHR_lightmap'] as
        | GLTFNodeLightmapExtension
        | undefined;
      if (nodeLightmap) validateGLTFNodeLightmaps(nodeLightmap, sourceMesh.primitives.length);
      for (const [primitiveIndex, primitive] of sourceMesh.primitives.entries()) {
        const binding =
          nodeLightmap?.lightmaps.find(lightmap => lightmap.primitive === primitiveIndex) ||
          primitive.material?.extensions?.['KHR_lightmap'];
        if (binding) {
          const coordinateSet = resolveTextureCoordinateSet(binding.lightmapTexture);
          // Validate the effective binding, after complete node overrides have been selected.
          assert(
            (coordinateSet === 0 || coordinateSet === 1) &&
              Boolean(primitive.attributes[`TEXCOORD_${coordinateSet}`])
          );
        }
      }
      const hasMorphTargets = sourceMesh.primitives.some(primitive =>
        Boolean(primitive.targets?.length)
      );
      const mesh =
        nodeLightmap ||
        instancing ||
        (combinedOptions.publishedTransforms && assignedMeshes.has(sourceMesh.id)) ||
        (hasMorphTargets && assignedMorphMeshes.has(sourceMesh.id))
          ? createNodeForGLTFMesh(
              device,
              sourceMesh,
              gltf,
              gltfMaterialIdToMaterialMap,
              combinedOptions,
              instancing || undefined,
              nodeLightmap
            )
          : gltfMeshIdToNodeMap.get(sourceMesh.id);
      if (!mesh) {
        throw new Error(`Cannot find mesh child ${gltfNode.mesh.id} of node ${idx}`);
      }
      const node = gltfNodeIndexToNodeMap.get(idx)!;
      const sharedMesh = gltfMeshIdToNodeMap.get(sourceMesh.id);
      const needsIndependentSkin =
        assignedMeshes.has(sourceMesh.id) &&
        (gltfNode.skin !== undefined || independentlySkinnedMeshes.has(sourceMesh.id));
      const ownedMesh =
        needsIndependentSkin && mesh === sharedMesh
          ? createNodeForGLTFMesh(
              device,
              sourceMesh,
              gltf,
              gltfMaterialIdToMaterialMap,
              combinedOptions
            )
          : mesh;
      node.add(ownedMesh);
      node.userData['gltfMesh'] = ownedMesh;
      assignedMeshes.add(sourceMesh.id);
      if (gltfNode.skin !== undefined) {
        independentlySkinnedMeshes.add(sourceMesh.id);
      }
      if (hasMorphTargets) {
        assignedMorphMeshes.add(sourceMesh.id);
        const targetCount =
          sourceMesh.primitives.find(primitive => primitive.targets?.length)?.targets?.length || 0;
        const weights =
          gltfNode.weights || sourceMesh.weights || new Array<number>(targetCount).fill(0);
        node.userData['morphMeshes'] = [ownedMesh];
        if (combinedOptions.modelOptions?.userData?.['gltfAnimatedCrowd']) {
          node.userData['morphWeights'] = [...weights];
        } else {
          setGLTFMorphWeights(node, weights);
        }
      }
    }
  });

  const scenes = gltf.scenes.map(gltfScene => {
    const children = (gltfScene.nodes || []).map(({id}) => {
      const child = gltfNodeIdToNodeMap.get(id);
      if (!child)
        throw new Error(`Cannot find child ${id} of scene ${gltfScene.name || gltfScene.id}`);
      return child;
    });
    return new GroupNode({
      id: gltfScene.name || gltfScene.id,
      children
    });
  });

  return {
    scenes,
    materials,
    gltfMeshIdToNodeMap,
    gltfNodeIdToNodeMap,
    gltfNodeIndexToNodeMap,
    generatedTextures,
    materialInstances
  };
}

/** Records every uploaded source texture without taking ownership of borrowed IBL textures. */
function parseOwnedPBRMaterial(
  device: Device,
  material: Parameters<typeof parsePBRMaterial>[1],
  attributes: Record<string, any>,
  options: ParseGLTFInternalOptions & {gltf: GLTFPostprocessed; validateAttributes?: boolean}
): ReturnType<typeof parsePBRMaterial> {
  const parsedMaterial = parsePBRMaterial(device, material, attributes, options);
  for (const texture of parsedMaterial.generatedTextures) {
    options.generatedTextures.add(texture);
  }
  return parsedMaterial;
}

/** Creates a `GroupNode` for one glTF node transform. */
function createNodeForGLTFNode(
  device: Device,
  gltfNode: GLTFNodePostprocessed,
  options: ParseGLTFInternalOptions
): GroupNode {
  return new GroupNode({
    id: gltfNode.name || gltfNode.id,
    children: [],
    matrix: gltfNode.matrix,
    display: gltfNode.extensions?.['KHR_node_visibility']?.visible !== false,
    selectable: gltfNode.extensions?.['KHR_node_selectability']?.selectable !== false,
    hoverable: gltfNode.extensions?.['KHR_node_hoverability']?.hoverable !== false,
    position: gltfNode.translation,
    rotation: gltfNode.rotation,
    scale: gltfNode.scale
  });
}

/** Creates a mesh group node containing one model node per glTF primitive. */
function createNodeForGLTFMesh(
  device: Device,
  gltfMesh: GLTFMeshPostprocessed,
  gltf: GLTFPostprocessed,
  gltfMaterialIdToMaterialMap: Map<string, Material>,
  options: ParseGLTFInternalOptions,
  instancing?: GLTFGPUInstancing,
  nodeLightmap?: GLTFNodeLightmapExtension,
  lightmapInstance?: GLTFLightmapInstance
): GroupNode {
  const gltfPrimitives = gltfMesh.primitives || [];
  const lightmapInstances = instancing && getGLTFLightmapInstances(instancing);
  if (lightmapInstances) {
    // Atlas batches currently use individual draws to preserve arbitrary I * B transforms on both backends.
    assert(
      Boolean(nodeLightmap?.lightmaps.length) ||
        gltfPrimitives.some(primitive => primitive.material?.extensions?.['KHR_lightmap'])
    );
    return new GroupNode({
      id: gltfMesh.name || gltfMesh.id,
      children: lightmapInstances.map(
        (instance, instanceIndex) =>
          new GroupNode({
            matrix: instancing.matrices[instanceIndex],
            children: [
              createNodeForGLTFMesh(
                device,
                gltfMesh,
                gltf,
                gltfMaterialIdToMaterialMap,
                options,
                undefined,
                nodeLightmap,
                instance
              )
            ]
          })
      )
    });
  }
  const primitives = gltfPrimitives.flatMap((gltfPrimitive, i) =>
    options.excludeGaussianSplatPrimitives && gltfPrimitive.extensions?.KHR_gaussian_splatting
      ? []
      : [
          createNodeForGLTFPrimitive({
            device,
            gltfPrimitive,
            primitiveIndex: i,
            gltfMesh,
            gltf,
            gltfMaterialIdToMaterialMap,
            options,
            instancing,
            nodeLightmap,
            lightmapInstance
          })
        ]
  );
  const mesh = new GroupNode({
    id: gltfMesh.name || gltfMesh.id,
    children: primitives
  });

  return mesh;
}

/** Input options for creating one renderable glTF primitive model node. */
type CreateNodeForGLTFPrimitiveOptions = {
  device: Device;
  gltfPrimitive: any;
  primitiveIndex: number;
  gltfMesh: GLTFMeshPostprocessed;
  gltf: GLTFPostprocessed;
  gltfMaterialIdToMaterialMap: Map<string, Material>;
  options: ParseGLTFInternalOptions;
  instancing?: GLTFGPUInstancing;
  nodeLightmap?: GLTFNodeLightmapExtension;
  lightmapInstance?: GLTFLightmapInstance;
};

/** Creates a renderable model node for one glTF primitive. */
function createNodeForGLTFPrimitive({
  device,
  gltfPrimitive,
  primitiveIndex,
  gltfMesh,
  gltf,
  gltfMaterialIdToMaterialMap,
  options,
  instancing,
  nodeLightmap,
  lightmapInstance
}: CreateNodeForGLTFPrimitiveOptions): ModelNode {
  const id = gltfPrimitive.name || `${gltfMesh.name || gltfMesh.id}-primitive-${primitiveIndex}`;
  const sourceVertexCount = getVertexCount(gltfPrimitive.attributes);
  const normalizedTopology = normalizeGLTFTopology(
    gltfPrimitive.mode ?? 4,
    gltfPrimitive.indices?.value,
    sourceVertexCount
  );

  const geometry = createGeometry(id, gltfPrimitive, normalizedTopology);
  const vertexCount = geometry.vertexCount;
  const morphTargetState = createGLTFMorphTargetState(gltfPrimitive, gltf, geometry);

  const lightmapOverride = nodeLightmap?.lightmaps.find(
    binding => binding.primitive === primitiveIndex
  );
  const sourceMaterial = lightmapOverride
    ? {
        ...gltfPrimitive.material,
        extensions: {...gltfPrimitive.material?.extensions, KHR_lightmap: lightmapOverride}
      }
    : gltfPrimitive.material;
  const parsedPPBRMaterial = parseOwnedPBRMaterial(device, sourceMaterial, geometry.attributes, {
    ...options,
    gltf
  });

  if (lightmapInstance && sourceMaterial?.extensions?.KHR_lightmap) {
    const binding = resolveGLTFLightmapTransform(
      sourceMaterial.extensions.KHR_lightmap,
      lightmapInstance
    );
    parsedPPBRMaterial.uniforms.lightmapUVTransform = binding.transform;
    parsedPPBRMaterial.uniforms.lightmapIntensity = binding.intensity;
  }

  const modelNode = createGLTFModel(device, {
    id,
    geometry,
    material:
      !sourceMaterial?.extensions?.KHR_lightmap && gltfPrimitive.material
        ? gltfMaterialIdToMaterialMap.get(gltfPrimitive.material.id) || null
        : null,
    parsedPPBRMaterial,
    modelOptions: options.modelOptions,
    publishedTransforms: options.publishedTransforms ?? undefined,
    vertexCount,
    bounds: [gltfPrimitive.attributes.POSITION.min, gltfPrimitive.attributes.POSITION.max],
    instanceMatrices: instancing?.matrices,
    usesLargeSkinPalette: usesLargeSkinPalette(
      gltfPrimitive.attributes.JOINTS_0,
      gltfPrimitive.attributes.JOINTS_1
    ),
    morphTargets: morphTargetState?.targets
  });

  if (gltfPrimitive.material && modelNode.model.material) {
    const sourceIndex = gltf.materials.findIndex(
      material => material.id === gltfPrimitive.material.id
    );
    registerMaterialInstance(options.materialInstances, sourceIndex, modelNode.model.material);
  }

  if (instancing) {
    modelNode.userData['gltfInstancing'] = instancing;
  }

  const sourceVariantMappings =
    gltfPrimitive.extensions?.['KHR_materials_variants']?.mappings || [];
  if (sourceVariantMappings.length) {
    const mappings = new Map<
      number,
      {material: Material; parameters: PrimitiveMaterialVariants['defaultParameters']}
    >();
    for (const mapping of sourceVariantMappings) {
      const mappedSourceMaterial =
        typeof mapping.material === 'number' ? gltf.materials[mapping.material] : mapping.material;
      const sourceMaterial = lightmapOverride
        ? {
            ...mappedSourceMaterial,
            extensions: {...mappedSourceMaterial?.extensions, KHR_lightmap: lightmapOverride}
          }
        : mappedSourceMaterial;
      let material = sourceMaterial && gltfMaterialIdToMaterialMap.get(sourceMaterial.id);
      if (!material) {
        continue;
      }
      const variantMaterial = parseOwnedPBRMaterial(
        device,
        sourceMaterial as any,
        geometry.attributes,
        {...options, gltf}
      );
      if (sourceMaterial.extensions?.KHR_lightmap) {
        if (lightmapInstance) {
          const binding = resolveGLTFLightmapTransform(
            sourceMaterial.extensions.KHR_lightmap,
            lightmapInstance
          );
          variantMaterial.uniforms.lightmapUVTransform = binding.transform;
          variantMaterial.uniforms.lightmapIntensity = binding.intensity;
        }
        material = createGLTFMaterial(device, {parsedPPBRMaterial: variantMaterial});
      }
      registerMaterialInstance(
        options.materialInstances,
        gltf.materials.indexOf(mappedSourceMaterial),
        material
      );
      for (const variantIndex of mapping.variants || []) {
        mappings.set(variantIndex, {
          material,
          parameters: {
            ...modelNode.model.parameters,
            ...variantMaterial.parameters,
            depthWriteEnabled: sourceMaterial.alphaMode !== 'BLEND',
            cullMode: sourceMaterial.doubleSided ? 'none' : 'back'
          }
        });
      }
    }
    modelNode.userData['gltfMaterialVariants'] = {
      defaultMaterial: modelNode.model.material,
      defaultParameters: {...modelNode.model.parameters},
      mappings
    } satisfies PrimitiveMaterialVariants;
  }

  if (morphTargetState) {
    modelNode.userData['morphTargets'] = morphTargetState;
  }

  // TODO this holds on to all the CPU side texture and attribute data
  // modelNode.material =  gltfPrimitive.material;

  return modelNode;
}

/** Selects a GPU palette only when this primitive can index past the uniform palette. */
function usesLargeSkinPalette(
  ...jointSets: ({max?: readonly number[]; value?: ArrayLike<number>} | undefined)[]
): boolean {
  for (const joints of jointSets) {
    if (!joints) {
      continue;
    }
    if (joints.max?.some(jointIndex => jointIndex >= SKIN_MAX_JOINTS)) {
      return true;
    }
    for (let jointIndex = 0; jointIndex < (joints.value?.length || 0); jointIndex++) {
      if (joints.value![jointIndex] >= SKIN_MAX_JOINTS) {
        return true;
      }
    }
  }
  return false;
}

function createGLTFMorphTargetState(
  gltfPrimitive: any,
  gltf: GLTFPostprocessed,
  geometry: Geometry
): GLTFMorphTargetState | undefined {
  if (!gltfPrimitive.targets?.length) {
    return undefined;
  }

  const baseAttributes: MorphTargetAttributes = {};
  for (const attributeName of ['POSITION', 'NORMAL', 'TANGENT'] as const) {
    const values = geometry.attributes[attributeName]?.value;
    if (values instanceof Float32Array) {
      baseAttributes[attributeName] = new Float32Array(values);
    }
  }

  const targets = gltfPrimitive.targets.map(
    (target: Record<string, number | {value?: Float32Array}>) => {
      const attributes: MorphTargetAttributes = {};
      for (const attributeName of ['POSITION', 'NORMAL', 'TANGENT'] as const) {
        const accessorReference = target[attributeName];
        const accessor =
          typeof accessorReference === 'number'
            ? gltf.accessors[accessorReference]
            : accessorReference;
        if (accessor?.value && ArrayBuffer.isView(accessor.value)) {
          attributes[attributeName] = decodeMorphTargetAttribute(accessor as GeometryAttribute);
        }
      }
      return attributes;
    }
  );

  return {geometry, baseAttributes, targets};
}

/** Computes the vertex count for a primitive without indices. */
function getVertexCount(attributes: any) {
  let vertexCount = Infinity;
  for (const attribute of Object.values(attributes)) {
    if (attribute) {
      const {value, size, components} = attribute as any;
      const attributeSize = size ?? components;
      if (value?.length !== undefined && attributeSize >= 1) {
        vertexCount = Math.min(vertexCount, value.length / attributeSize);
      }
    }
  }
  if (!Number.isFinite(vertexCount)) {
    throw new Error('Could not determine vertex count from attributes');
  }
  return vertexCount;
}

/** Converts glTF primitive attributes and indices into a luma.gl `Geometry`. */
function createGeometry(
  id: string,
  gltfPrimitive: any,
  normalizedTopology: NormalizedGLTFTopology
): Geometry {
  const attributes: Record<string, GeometryAttribute> = {};
  for (const [attributeName, attribute] of Object.entries(gltfPrimitive.attributes)) {
    const {components, size, value, normalized} = attribute as GeometryAttribute & {
      components?: number;
    };

    const isMorphAttribute =
      attributeName === 'POSITION' || attributeName === 'NORMAL' || attributeName === 'TANGENT';
    const shouldDecode = Boolean(gltfPrimitive.targets?.length && isMorphAttribute);
    attributes[attributeName] = {
      size: size ?? components,
      value: shouldDecode
        ? decodeMorphTargetAttribute({value, normalized} as GeometryAttribute)
        : value,
      normalized: shouldDecode ? false : normalized
    };
  }

  return new Geometry({
    id,
    topology: normalizedTopology.topology,
    indices: normalizedTopology.indices ?? gltfPrimitive.indices?.value,
    attributes
  });
}

function getGLTFMaterialId(gltfMaterial: GLTFMaterialPostprocessed, materialIndex: number): string {
  return gltfMaterial.name || gltfMaterial.id || `material-${materialIndex}`;
}

function registerMaterialInstance(
  instances: Map<number, Material[]>,
  sourceIndex: number,
  material: Material
): void {
  if (sourceIndex < 0) return;
  const materials = instances.get(sourceIndex) || [];
  if (!materials.includes(material)) materials.push(material);
  instances.set(sourceIndex, materials);
}
